/**
 * Invoicing module: line items, tax, discounts and totals.
 *
 * All monetary amounts are integer minor units (e.g. cents) so that sums
 * never accumulate floating-point error. Rates are expressed as fractions
 * (0.2 means 20%).
 */

/** A single billable line on an invoice. */
export interface LineItem {
  /** Human-readable description shown on the invoice. */
  description: string;
  /** Price of one unit, in minor units. */
  unitPrice: number;
  /** Number of units; must be a positive integer. */
  quantity: number;
  /** Tax rate applied to this line, as a fraction. Defaults to 0. */
  taxRate?: number;
}

/** A discount applied to the invoice subtotal. */
export type Discount =
  | { kind: "percent"; value: number }
  | { kind: "fixed"; value: number };

/** The computed monetary breakdown of an invoice, in minor units. */
export interface InvoiceTotals {
  /** Sum of all line amounts before discount and tax. */
  subtotal: number;
  /** Total discount taken off the subtotal. */
  discount: number;
  /** Total tax charged, after discount has been applied. */
  tax: number;
  /** Amount due: subtotal - discount + tax. */
  total: number;
}

/** An invoice: its line items, optional discount, and computed totals. */
export interface Invoice {
  items: LineItem[];
  discount?: Discount;
  totals: InvoiceTotals;
}

/**
 * Rounds a minor-unit amount to the nearest whole unit.
 * Halves round away from zero.
 */
function round(amount: number): number {
  return Math.sign(amount) * Math.round(Math.abs(amount));
}

/**
 * Validates a line item, throwing if it cannot be billed.
 *
 * @throws RangeError if the price, quantity or tax rate is out of range.
 */
export function assertValidLineItem(item: LineItem): void {
  if (!Number.isInteger(item.unitPrice) || item.unitPrice < 0) {
    throw new RangeError(`Invalid unit price for "${item.description}"`);
  }
  if (!Number.isInteger(item.quantity) || item.quantity <= 0) {
    throw new RangeError(`Invalid quantity for "${item.description}"`);
  }
  const rate = item.taxRate ?? 0;
  if (!Number.isFinite(rate) || rate < 0) {
    throw new RangeError(`Invalid tax rate for "${item.description}"`);
  }
}

/** Returns the pre-tax, pre-discount amount for one line (price x quantity). */
export function lineAmount(item: LineItem): number {
  assertValidLineItem(item);
  return item.unitPrice * item.quantity;
}

/**
 * Computes the discount for a given subtotal.
 *
 * The result is capped at the subtotal, so a discount can never make an
 * invoice negative.
 *
 * @throws RangeError if a percent discount is outside 0..1 or a fixed
 *   discount is negative or not an integer.
 */
export function computeDiscount(subtotal: number, discount?: Discount): number {
  if (!discount) return 0;
  if (discount.kind === "percent") {
    if (!(discount.value >= 0 && discount.value <= 1)) {
      throw new RangeError("Percent discount must be between 0 and 1");
    }
    return Math.min(subtotal, round(subtotal * discount.value));
  }
  if (!Number.isInteger(discount.value) || discount.value < 0) {
    throw new RangeError("Fixed discount must be a non-negative integer");
  }
  return Math.min(subtotal, discount.value);
}

/**
 * Computes the tax on all lines after discount.
 *
 * The discount is spread across lines in proportion to their amounts, so each
 * line is taxed at its own rate on its discounted share. Tax is rounded once
 * per line.
 */
export function computeTax(items: LineItem[], discount: number): number {
  const subtotal = items.reduce((sum, item) => sum + lineAmount(item), 0);
  if (subtotal === 0) return 0;
  return items.reduce((sum, item) => {
    const amount = lineAmount(item);
    const share = (amount / subtotal) * discount;
    return sum + round((amount - share) * (item.taxRate ?? 0));
  }, 0);
}

/**
 * Computes the subtotal, discount, tax and total for a set of line items.
 *
 * @throws RangeError if any item or the discount is invalid.
 */
export function computeTotals(items: LineItem[], discount?: Discount): InvoiceTotals {
  const subtotal = items.reduce((sum, item) => sum + lineAmount(item), 0);
  const discountAmount = computeDiscount(subtotal, discount);
  const tax = computeTax(items, discountAmount);
  return { subtotal, discount: discountAmount, tax, total: subtotal - discountAmount + tax };
}

/** Builds an invoice from line items and an optional discount. */
export function createInvoice(items: LineItem[], discount?: Discount): Invoice {
  return { items, discount, totals: computeTotals(items, discount) };
}
